  Details(r,paint,steel,dark,trim);Weather(paint);var mats=new[]{paint,steel,dark,trim};var mesh=Bake(r,mats);mesh.name="HarborCrane";string path=Root+"/HarborCrane.asset";var previous=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(previous){EditorUtility.CopySerialized(mesh,previous);Object.DestroyImmediate(mesh);mesh=previous;mesh.UploadMeshData(false);}else AssetDatabase.CreateAsset(mesh,path);foreach(var g in pieces)Object.DestroyImmediate(g);pieces.Clear();root.AddComponent<MeshFilter>().sharedMesh=mesh;root.AddComponent<MeshRenderer>().sharedMaterials=mats;for(int x=-1;x<=1;x+=2)for(int z=-1;z<=1;z+=2){var collider=root.AddComponent<BoxCollider>();collider.center=new Vector3(x*2.9f,5.3f,z*3);collider.size=new Vector3(.8f,10.6f,.8f);}var prefab=PrefabUtility.SaveAsPrefabAsset(root,Root+"/HarborCrane.prefab");Object.DestroyImmediate(root);
