 static void Cylinder(Transform r,string name,Vector3 pos,Vector3 size,Material mat){var g=GameObject.CreatePrimitive(PrimitiveType.Cylinder);g.name=name;g.transform.SetParent(r,false);g.transform.localPosition=pos;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=mat;Object.DestroyImmediate(g.GetComponent<Collider>());pieces.Add(g);}
 static void Weather(Material paint){string path=Root+"/PaintWeathering.png";var tex=new Texture2D(256,256,TextureFormat.RGB24,false);var rand=new System.Random(41);for(int y=0;y<256;y++)for(int x=0;x<256;x++){float n=(float)rand.NextDouble();float streak=Mathf.PerlinNoise(x*.17f,y*.015f);float grime=Mathf.Pow(1-y/255f,4)*.24f;float f=.83f+n*.17f-grime;var c=new Color(f,f*.97f,f*.9f);if(streak>.76f && n>.64f)c=new Color(.67f,.54f,.36f);tex.SetPixel(x,y,c);}tex.Apply();File.WriteAllBytes(path,tex.EncodeToPNG());Object.DestroyImmediate(tex);AssetDatabase.ImportAsset(path);paint.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(path));paint.SetFloat("_Metallic",.28f);paint.SetFloat("_Smoothness",.24f);EditorUtility.SetDirty(paint);}
